import { csvCell } from './geoJsonToCsv.js'

const endpoint = 'https://geocode-api.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates'

/**
 * Request one stored geocode in WGS84 and use its first address candidate.
 * POST keeps the access token out of the URL; requests time out after 20 seconds.
 * Input: query '380 New York St, Redlands, CA' and an ArcGIS access token.
 * Output: { lng:-117.1957, lat:34.0572, label:'380 New York St, Redlands, California' },
 * or null when no candidate matches. HTTP/API errors and invalid coordinates throw.
 */
async function geocodeAddress(query, accessToken, signal) {
  const timeout = AbortSignal.timeout(20000)
  const response = await fetch(endpoint, {
    method: 'POST',
    body: new URLSearchParams({
      f: 'json',
      singleLine: query,
      outSR: '4326',
      maxLocations: '1',
      forStorage: 'true',
      token: accessToken,
    }),
    signal: signal ? AbortSignal.any([signal, timeout]) : timeout,
  })
  if (!response.ok)
    throw new Error(`ArcGIS returned HTTP ${response.status}. Check your access token or service availability.`)
  const data = await response.json()
  if (data.error) {
    const code = data.error.code
    if ([401, 403, 498, 499].includes(code))
      throw new Error('ArcGIS access token is invalid, expired or missing stored-geocoding privileges.')
    if (code === 429) throw new Error('ArcGIS rate limit reached. Try again later.')
    throw new Error('ArcGIS could not complete the geocoding request.')
  }
  if (!Array.isArray(data.candidates)) throw new Error('ArcGIS returned an invalid geocoding response.')
  if (!data.candidates.length) return null
  const candidate = data.candidates[0],
    lng = candidate.location?.x,
    lat = candidate.location?.y
  if (!Number.isFinite(lng) || !Number.isFinite(lat) || Math.abs(lng) > 180 || Math.abs(lat) > 90) {
    throw new Error('ArcGIS returned invalid WGS84 coordinates.')
  }
  return { lng, lat, label: typeof candidate.address === 'string' ? candidate.address : '' }
}

/**
 * Geocode non-empty addresses sequentially, adding optional city/province text.
 * Keep every source row in CSV; unmatched/empty addresses get blank generated cells.
 * GeoJSON contains matched Point features with the original columns and address label.
 * Generated column names get _1, _2, ... suffixes when source headers already use them.
 * Wait 150 ms between requests; onProgress receives (done,total). Aborting or a service
 * error stops conversion before any files are returned, preserving the original input.
 * Input: { headers:['address','id'], rows:[['Redlands, CA','01'],['','02']] }, column 0,
 * options { accessToken:'...', city:'', province:'' }.
 * Output: { csv:'address,id,lat,lng,geocoded_address\nRedlands...,01,34...,-117...,Redlands...\n,02,,,\n',
 * collection:{ type:'FeatureCollection', features:[{ type:'Feature', properties:{ address:'Redlands, CA', id:'01',
 * geocoded_address:'Redlands...' }, geometry:{ type:'Point', coordinates:[-117...,34...] } }] }, matched:1, unmatched:1 }.
 */
// shortcut: files and outputs stay in memory, and geocoding is serial; use a server-side batch job for large address lists.
export async function geocodeCsv(csv, column, options, onProgress = () => {}) {
  const { accessToken, city = '', province = '', signal } = options
  if (!Number.isInteger(column) || column < 0 || column >= csv.headers.length)
    throw new Error('Choose the address or postal code column.')
  if (typeof accessToken !== 'string' || !accessToken.trim())
    throw new Error('Enter an ArcGIS API key or access token with stored-geocoding privileges.')
  const generated = ['lat', 'lng', 'geocoded_address'].map((name) => {
    let candidate = name
    for (let suffix = 1; csv.headers.includes(candidate); suffix++) candidate = `${name}_${suffix}`
    return candidate
  })
  const rows = [[...csv.headers, ...generated]],
    features = []
  let requested = false
  for (const [index, row] of csv.rows.entries()) {
    signal?.throwIfAborted()
    const address = row[column].trim()
    let candidate = null
    if (address) {
      if (requested) await new Promise((resolve) => setTimeout(resolve, 150))
      signal?.throwIfAborted()
      const query = [address, city.trim(), province.trim()].filter(Boolean).join(', ')
      try {
        candidate = await geocodeAddress(query, accessToken.trim(), signal)
      } catch (error) {
        signal?.throwIfAborted()
        const reason = error.name === 'TimeoutError' ? 'ArcGIS request timed out. Try again later.' : error.message
        throw new Error(`Could not geocode CSV row ${index + 2}: ${reason}`, { cause: error })
      }
      requested = true
    }
    signal?.throwIfAborted()
    rows.push([...row, ...(candidate ? [candidate.lat, candidate.lng, candidate.label] : ['', '', ''])])
    if (candidate)
      features.push({
        type: 'Feature',
        properties: {
          ...Object.fromEntries(csv.headers.map((name, index) => [name, row[index]])),
          [generated[2]]: candidate.label,
        },
        geometry: { type: 'Point', coordinates: [candidate.lng, candidate.lat] },
      })
    onProgress(index + 1, csv.rows.length)
  }
  return {
    csv: rows.map((row) => row.map(csvCell).join(',')).join('\n') + '\n',
    collection: { type: 'FeatureCollection', features },
    matched: features.length,
    unmatched: csv.rows.length - features.length,
  }
}
