<script setup>
import { computed, onBeforeUnmount, ref, shallowRef } from 'vue'
import { parseCsv } from './csvGeoJsonMerger.js'
import { geocodeCsv } from './csvGeocoding.js'
import { zipFiles } from '../shared/archive.js'
import { downloadFile } from '../shared/download.js'

const source = shallowRef(null)
const column = ref(null),
  city = ref(''),
  province = ref(''),
  accessToken = ref('')
const loading = ref(false),
  converting = ref(false),
  done = ref(0),
  error = ref(''),
  result = ref(''),
  cancelled = ref(false)
const busy = computed(() => loading.value || converting.value)
const columns = computed(() => source.value?.csv.headers.map((title, value) => ({ title, value })) ?? [])
const canExport = computed(() => source.value && Number.isInteger(column.value) && accessToken.value.trim())
let controller
function clearResult() {
  error.value = ''
  result.value = ''
  cancelled.value = false
}
function cancelConversion() {
  controller?.abort()
}
onBeforeUnmount(cancelConversion)

async function loadCsv(selected) {
  clearResult()
  source.value = null
  column.value = null
  done.value = 0
  const file = Array.isArray(selected) ? selected[0] : selected
  if (!file) return
  loading.value = true
  try {
    source.value = { stem: file.name.replace(/\.[^.]+$/, ''), csv: await parseCsv(await file.text()) }
  } catch (failure) {
    error.value = `Could not read CSV: ${failure.message}`
  } finally {
    loading.value = false
  }
}
async function exportFiles() {
  if (!canExport.value || busy.value) return
  clearResult()
  converting.value = true
  done.value = 0
  controller = new AbortController()
  const signal = controller.signal
  try {
    const { csv, stem } = source.value
    const output = await geocodeCsv(
      csv,
      column.value,
      {
        city: city.value,
        province: province.value,
        accessToken: accessToken.value,
        signal,
      },
      (processed) => {
        done.value = processed
      },
    )
    signal.throwIfAborted()
    const zip = await zipFiles([
      { name: `${stem}_geocoded.csv`, content: output.csv },
      { name: `${stem}_points.geojson`, content: JSON.stringify(output.collection) },
    ])
    signal.throwIfAborted()
    downloadFile(zip, `${stem}_geocoded.zip`, 'application/zip')
    result.value = `${output.matched} rows geocoded; ${output.unmatched} rows unmatched. Downloaded: ${stem}_geocoded.zip.`
  } catch (failure) {
    if (signal.aborted) cancelled.value = true
    else error.value = failure.name === 'TimeoutError' ? 'ArcGIS request timed out. Try again later.' : failure.message
  } finally {
    converting.value = false
    controller = undefined
  }
}
const fileUpload = ref()
</script>

<template>
  <!-- Bố cục: Form nhận CSV, cột địa chỉ và khóa ArcGIS; tiến độ/hủy nằm cạnh thao tác xuất, các VaAlert báo lỗi hoặc kết quả. -->
  <section>
    <h1 class="page-title">CSV → GeoJSON</h1>
    <VaCard>
      <VaCardContent>
        <!-- Đầu vào và cấu hình xuất dùng control Vuestic; submit gọi hàm xử lý của trang, busy khóa thao tác khi đang chạy. -->
        <VaForm novalidate class="space-y-4" @submit.prevent="exportFiles" @input="clearResult">
          <VaFileUpload
            id="geocode-csv-file"
            v-model="fileUpload"
            type="single"
            upload-button-text="CSV file"
            file-types=".csv,text/csv"
            :disabled="busy"
            @update:modelValue="loadCsv"
          />
          <VaProgressBar v-if="loading" indeterminate aria-label="Reading file" />
          <p v-if="source" class="text-sm text-secondary" data-testid="geocode-summary">
            {{ source.csv.rows.length }} rows
          </p>
          <VaSelect
            id="geocode-column"
            v-model="column"
            text-by="title"
            value-by="value"
            label="Address or postal code column"
            aria-label="Address or postal code column"
            :options="columns"
            :disabled="busy || !source"
            @update:modelValue="clearResult"
          />
          <VaInput
            id="geocode-city"
            v-model="city"
            label="City [optional]"
            input-aria-label="City [optional]"
            :disabled="busy"
          />
          <VaInput
            id="geocode-province"
            v-model="province"
            label="Province [optional]"
            input-aria-label="Province [optional]"
            :disabled="busy"
          />
          <VaInput
            id="geocode-token"
            v-model="accessToken"
            label="ArcGIS API key / access token"
            input-aria-label="ArcGIS API key / access token"
            type="password"
            autocomplete="off"
            required
            :disabled="busy"
          />
          <VaProgressBar
            v-if="converting"
            :model-value="source ? (done / source.csv.rows.length) * 100 : 0"
            color="primary"
            aria-label="Geocoding progress"
          />
          <p v-if="converting" role="status" data-testid="geocode-progress">
            {{ done }} / {{ source.csv.rows.length }}
          </p>
          <VaButton type="submit" color="primary" :disabled="!canExport || busy" :loading="converting"
            >Export enriched CSV &amp; GeoJSON</VaButton
          >
          <VaButton v-if="converting" type="button" @click="cancelConversion">Cancel</VaButton>
        </VaForm>
        <!-- Thông báo đọc/xuất dữ liệu nằm gần thao tác liên quan; điều kiện v-if quyết định lúc hiển thị. -->
        <VaAlert v-if="error" color="danger" class="mt-4" role="alert" data-testid="tool-error">{{ error }}</VaAlert>
        <VaAlert v-if="cancelled" color="info" class="mt-4" role="status" data-testid="geocode-cancelled"
          >Cancelled.</VaAlert
        >
        <VaAlert v-if="result" color="success" class="mt-4" role="status" data-testid="tool-result">{{
          result
        }}</VaAlert>
      </VaCardContent>
    </VaCard>
  </section>
</template>
