import center from '@turf/center'
import { coordEach } from '@turf/meta'

/**
 * Turn one value into a CSV cell. Objects become JSON; null becomes empty.
 * Quotes are doubled and cells containing commas, quotes or newlines are quoted.
 * Input -> output: 'School, north' -> '"School, north"'; null -> ''.
 * Input -> output: { h: 10 } -> '"{""h"":10}"'.
 */
export function csvCell(value) {
  if (value == null) return ''
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value)
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text
}

/**
 * Collect all property names in first-seen order. Write one row per feature,
 * starting with its zero-based index and bounding-box center as latitude/longitude.
 * Keep rows with unusable geometry, leaving their latitude/longitude empty.
 * Rename generated columns with _1, _2, ... when a source property has that name.
 * The collection and its properties are not changed.
 *
 * Input:
 *   { type: 'FeatureCollection', features: [{ type: 'Feature',
 *     properties: { name: 'Office' }, geometry: { type: 'Point', coordinates: [10, 20] } }] }
 * Output: 'sn,lat,lng,name\n0,20,10,Office\n'.
 * Input with properties { lat: 'north' } uses header 'sn,lat_1,lng,lat'.
 */
// shortcut: files and CSV output stay in memory; use a worker with chunks if real inputs freeze the UI.
export function geoJsonToCsv(collection) {
  const keys = [...new Set(collection.features.flatMap((feature) => Object.keys(feature.properties ?? {})))]
  const generated = ['sn', 'lat', 'lng'].map((name) => {
    let candidate = name
    for (let suffix = 1; keys.includes(candidate); suffix++) candidate = `${name}_${suffix}`
    return candidate
  })
  const rows = [[...generated, ...keys]]
  collection.features.forEach((feature, index) => {
    let coordinates = ['', '']
    try {
      coordEach(feature, (coordinate) => {
        if (!Array.isArray(coordinate) || coordinate.length < 2 || !coordinate.slice(0, 2).every(Number.isFinite)) {
          throw new Error('Geometry contains invalid longitude/latitude.')
        }
      })
      const [lng, lat] = center(feature).geometry.coordinates
      if (Number.isFinite(lng) && Number.isFinite(lat)) coordinates = [lat, lng]
    } catch {
      // Attribute-only features still need their own CSV row.
    }
    rows.push([index, ...coordinates, ...keys.map((key) => feature.properties?.[key])])
  })
  return rows.map((row) => row.map(csvCell).join(',')).join('\n') + '\n'
}
