import csvtojson from 'csvtojson'

/**
 * Parse CSV text into header names and data rows. All cells remain strings.
 * The first record is the header; blank data records are skipped. Empty or
 * duplicate headers, missing data and inconsistent column counts throw errors.
 *
 * Input:
 *   'id,name\n101,Office\n102,"School, north"'
 * Output:
 *   {
 *     headers: ['id', 'name'],
 *     rows: [['101', 'Office'], ['102', 'School, north']]
 *   }
 */
// shortcut: whole files stay in browser memory; use a worker with chunks if real inputs freeze the UI.
export async function parseCsv(text) {
  // Remove the BOM before parsing so the first header contains only its name.
  const [headers = [], ...dataRows] = await csvtojson({ noheader: true, output: 'csv' }).fromString(
    text.replace(/^\uFEFF/, ''),
  )

  if (!headers.length || headers.some((header) => !header)) {
    throw new Error('CSV must have a non-empty header for every column.')
  }
  if (new Set(headers).size !== headers.length) {
    throw new Error('CSV column names must be unique.')
  }
  const rows = dataRows.filter((row) => row.some((cell) => cell !== ''))
  if (!rows.length) throw new Error('CSV must contain at least one data row.')
  // Each data record must have exactly as many cells as the header.
  rows.forEach((row, index) => {
    if (row.length !== headers.length) {
      throw new Error(`CSV row ${index + 2} has ${row.length} columns; expected ${headers.length}.`)
    }
  })
  return { headers, rows }
}

/**
 * Parse JSON text and check for a non-empty FeatureCollection of Features.
 * Properties must be an object, null, or absent. Geometry is left unchanged.
 * Invalid JSON or an invalid collection/feature structure throws an error.
 *
 * Input:
 *   '{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":101},"geometry":null}]}'
 * Output:
 *   {
 *     type: 'FeatureCollection',
 *     features: [{ type: 'Feature', properties: { id: 101 }, geometry: null }]
 *   }
 */
export function parseGeoJson(text) {
  const collection = JSON.parse(text.replace(/^\uFEFF/, ''))
  if (collection?.type !== 'FeatureCollection' || !Array.isArray(collection.features)) {
    throw new Error('GeoJSON must be a FeatureCollection with a features array.')
  }
  if (!collection.features.length) throw new Error('GeoJSON must contain at least one feature.')
  collection.features.forEach((feature, index) => {
    if (
      feature?.type !== 'Feature' ||
      (feature.properties != null && (typeof feature.properties !== 'object' || Array.isArray(feature.properties)))
    ) {
      throw new Error(`GeoJSON feature ${index + 1} must be a Feature with object or null properties.`)
    }
  })
  return collection
}

/**
 * Convert a string, number or boolean to a trimmed key. Case and leading
 * zeroes are preserved. Empty values and other types cannot match.
 *
 * Examples (input -> output):
 *   ' 101 ' -> '101'
 *   101 -> '101'
 *   0 -> '0'
 *   false -> 'false'
 *   '001' -> '001'
 *   'ABC' -> 'ABC'
 *   '' -> null
 *   null -> null
 *   undefined -> null
 *   [] -> null
 *   {} -> null
 */
export function joinKey(value) {
  return ['string', 'number', 'boolean'].includes(typeof value) ? String(value).trim() || null : null
}

/**
 * 1. Index GeoJSON features by the selected property after key normalization.
 * 2. Look up the matching features for each CSV row.
 * 3. Copy CSV columns except the join column into new feature properties.
 * 4. Return each matching source feature once and count matched CSV rows.
 *
 * Repeated CSV keys overwrite previous values: the last row wins. Several
 * features can share a key and all are included. Unmatched features are omitted.
 * Source data is not modified; geometry references are preserved.
 *
 * Input:
 *   csv = {
 *     headers: ['id', 'name'],
 *     rows: [['101', 'Office'], ['101', 'Updated'], ['999', 'Unused']]
 *   }
 *   geoJson = {
 *     type: 'FeatureCollection',
 *     features: [
 *       { type: 'Feature', properties: { buildingId: 101, name: 'Before' }, geometry: null },
 *       { type: 'Feature', properties: { buildingId: 102, name: 'Other' }, geometry: null }
 *     ]
 *   }
 *   csvColumn = 0
 *   geoJsonProperty = 'buildingId'
 * Output:
 *   {
 *     collection: {
 *       type: 'FeatureCollection',
 *       features: [
 *         { type: 'Feature', properties: { buildingId: 101, name: 'Updated' }, geometry: null }
 *       ]
 *     },
 *     matchedRows: 2
 *   }
 *
 * No-match input: the same GeoJSON and join fields, but rows: [['999', 'Unused']].
 * No-match output: { collection: { type: 'FeatureCollection', features: [] }, matchedRows: 0 }.
 */
export function mergeCsvGeoJson(csv, geoJson, csvColumn, geoJsonProperty, lbnl = false) {
  if (
    !Number.isInteger(csvColumn) ||
    csvColumn < 0 ||
    csvColumn >= csv.headers.length ||
    !geoJson.features.some((feature) => Object.hasOwn(feature.properties ?? {}, geoJsonProperty))
  ) {
    throw new Error('Choose a CSV column and a GeoJSON property to match.')
  }

  // Group every source feature with the same normalized key in one lookup list.
  const byKey = new Map()
  for (const feature of geoJson.features) {
    const key = joinKey(feature.properties?.[geoJsonProperty])
    if (key === null) continue
    if (!byKey.has(key)) byKey.set(key, [])
    byKey.get(key).push(feature)
  }

  // Use source object identity so distinct features sharing a key stay distinct.
  const merged = new Map()
  let matchedRows = 0
  for (const row of csv.rows) {
    const targets = byKey.get(joinKey(row[csvColumn]))
    if (!targets) continue
    // Copy literal column names, excluding the selected CSV join column.
    // fromEntries and spread keep '__proto__' as an own data property.
    const values = Object.fromEntries(
      csv.headers.flatMap((header, index) => (index === csvColumn ? [] : [[header, row[index]]])),
    )
    for (const feature of targets) {
      // Clone the previous output so repeated rows overwrite values without modifying the input.
      let properties = { ...(merged.get(feature)?.properties ?? feature.properties) }
      if (lbnl) {
        if (csv.headers.length > 1) {
          const additional = properties.additional_json
          properties.additional_json = {
            ...(additional && typeof additional === 'object' && !Array.isArray(additional) ? additional : {}),
            ...values,
          }
        }
      } else {
        properties = { ...properties, ...values }
      }
      merged.set(feature, { ...feature, properties })
    }
    // Count the CSV row once, even when it matches several features.
    matchedRows++
  }
  // Output follows first-match order and contains only matching features.
  return {
    collection: { type: 'FeatureCollection', features: [...merged.values()] },
    matchedRows,
  }
}

/**
 * Match rows with the same key rules as mergeCsvGeoJson, then write CSV columns
 * except the join column under additional_json. Existing object fields stay;
 * repeated CSV rows overwrite earlier values. Null, arrays and scalar containers
 * become objects. Source properties and the source container are not changed.
 *
 * Input: CSV headers ['id', 'h'], rows [['1', '12']], join column 0;
 *        GeoJSON properties { id: 1, name: 'Office', additional_json: { year: 2000 } }, join property 'id'.
 * Output: matchedRows 1; feature properties
 *         { id: 1, name: 'Office', additional_json: { year: 2000, h: '12' } }.
 */
export function mergeCsvGeoJsonLbnl(csv, geoJson, csvColumn, geoJsonProperty) {
  return mergeCsvGeoJson(csv, geoJson, csvColumn, geoJsonProperty, true)
}
